<?php
namespace Upyun; class Signature { const SIGN_MULTIPART = 1; const SIGN_VIDEO = 2; const SIGN_VIDEO_NO_OPERATOR = 3; public static function getHeaderSign($bucketConfig, $method, $path, $contentMd5 = null) { $gmtDate = gmdate('D, d M Y H:i:s \G\M\T'); $policy = null; $sign = self::getBodySignature($bucketConfig, $method, $path, $gmtDate, $policy, $contentMd5); $headers = array( 'Authorization' => $sign, 'Date' => $gmtDate, 'User-agent' => 'Php-Sdk/' . $bucketConfig->getVersion() ); return $headers; } public static function getPurgeSignHeader(Config $bucketConfig, $urlString) { $gmtDate = gmdate('D, d M Y H:i:s \G\M\T'); $sign = md5("$urlString&{$bucketConfig->bucketName}&$gmtDate&{$bucketConfig->operatorPassword}"); return array( 'Authorization' => "UpYun {$bucketConfig->bucketName}:{$bucketConfig->operatorName}:$sign", 'Date' => $gmtDate, 'User-agent' => 'Php-Sdk/' . $bucketConfig->getVersion() . ' (purge api)' ); } public static function getBodySignature(Config $bucketConfig, $method, $uri, $date = null, $policy = null, $contentMd5 = null) { $data = array( $method, $uri ); if ($date) { $data[] = $date; } if ($policy) { $data[] = $policy; } if ($contentMd5) { $data[] = $contentMd5; } $signature = base64_encode(hash_hmac('sha1', implode('&', $data), $bucketConfig->operatorPassword, true)); return 'UPYUN ' . $bucketConfig->operatorName . ':' . $signature; } } 